<?php require_once dirname(__DIR__,2).'/header.php'; ?><main class="fg-wrap"><section class="fg-card"><span class="eyebrow">FREE ONLINE TOOL</span><h1>Favicon Generator</h1><p class="fg-note">Create favicon PNG files locally in your browser. No account, upload, tracking or database is required.</p><div class="fg-grid"><div class="fg-preview"><canvas id="preview" width="256" height="256"></canvas></div><div class="fg-controls"><div class="fg-field"><label>Source</label><div class="fg-sources"><button class="active" data-source="image" type="button">Image</button><button data-source="emoji" type="button">Emoji</button><button data-source="text" type="button">Text</button></div><input id="file" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml"><input id="emoji" type="text" value="🚀" maxlength="8" hidden><input id="text" type="text" value="S" maxlength="3" hidden></div><div class="fg-field"><label>Background</label><input id="bg" type="color" value="#FFFFFF"><label style="margin-top:9px">Foreground</label><input id="fg" type="color" value="#1537D4"><label style="margin-top:9px">Padding</label><input id="pad" type="range" min="0" max="35" value="10"></div><div class="fg-field"><label>Sizes</label><div class="fg-sizes" id="sizes"></div></div><div class="fg-actions"><button id="generate" type="button">Generate Favicons</button><button class="secondary" id="reset" type="button">Reset</button></div><div class="fg-note" id="status">Choose a source and generate your favicons.</div></div></div><div class="fg-results" id="results"></div></section></main><?php require_once dirname(__DIR__,2).'/footer.php'; ?><script>
(()=>{const $=id=>document.getElementById(id),canvas=$('preview'),ctx=canvas.getContext('2d');let source='image',img=null;const sizes=[16,32,48,64,128,180,192,256,512],chosen=new Set(sizes);sizes.forEach(s=>{const b=document.createElement('button');b.className='fg-size active';b.textContent=s+'×'+s;b.type='button';b.onclick=()=>{chosen.has(s)?chosen.delete(s):chosen.add(s);b.classList.toggle('active',chosen.has(s))};$('sizes').append(b)});function draw(c,size){const x=c.getContext('2d'),p=size*+$('pad').value/100;x.clearRect(0,0,size,size);x.fillStyle=$('bg').value;x.fillRect(0,0,size,size);if(source==='image'&&img){const s=Math.min((size-p*2)/img.width,(size-p*2)/img.height);const w=img.width*s,h=img.height*s;x.drawImage(img,(size-w)/2,(size-h)/2,w,h)}else{x.fillStyle=$('fg').value;x.textAlign='center';x.textBaseline='middle';x.font=(source==='emoji'?Math.floor(size*.72):'800 '+Math.floor(size*.62))+'px Arial,sans-serif';x.fillText(source==='emoji'?($('emoji').value||'🚀'):($('text').value||'S'),size/2,size/2)}return c}function refresh(){draw(canvas,256)}document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{source=b.dataset.source;document.querySelectorAll('[data-source]').forEach(x=>x.classList.toggle('active',x===b));$('file').hidden=source!=='image';$('emoji').hidden=source!=='emoji';$('text').hidden=source!=='text';refresh()});$('file').onchange=e=>{const f=e.target.files?.[0];if(!f)return;const u=URL.createObjectURL(f),i=new Image();i.onload=()=>{img=i;URL.revokeObjectURL(u);refresh();$('status').textContent='Image ready.'};i.onerror=()=>URL.revokeObjectURL(u);i.src=u};$('bg').oninput=refresh;$('fg').oninput=refresh;$('pad').oninput=refresh;$('emoji').oninput=refresh;$('text').oninput=refresh;$('generate').onclick=()=>{const out=$('results');out.innerHTML='';if(!chosen.size){$('status').textContent='Select at least one size.';return}if(source==='image'&&!img){$('status').textContent='Upload an image first.';return}[...chosen].sort((a,b)=>a-b).forEach(s=>{const c=draw(document.createElement('canvas'),s),card=document.createElement('div');card.className='fg-result';const d=document.createElement('canvas');d.width=d.height=64;d.getContext('2d').drawImage(c,0,0,64,64);const button=document.createElement('button');button.textContent='Download';button.onclick=()=>{c.toBlob(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='favicon-'+s+'x'+s+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)},'image/png')};card.append(d,document.createTextNode(s+' × '+s),button);out.append(card)});$('status').textContent=chosen.size+' favicon sizes generated.'};$('reset').onclick=()=>{img=null;$('file').value='';$('bg').value='#FFFFFF';$('fg').value='#1537D4';$('pad').value=10;source='image';document.querySelectorAll('[data-source]').forEach((b,i)=>b.classList.toggle('active',i===0));$('file').hidden=false;$('emoji').hidden=true;$('text').hidden=true;$('results').innerHTML='';refresh();$('status').textContent='Choose a source and generate your favicons.'};$('file').hidden=false;$('emoji').hidden=true;$('text').hidden=true;refresh()})();
</script>



